import{totalKm,calculate,validData}from './model.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),id=()=>crypto.randomUUID(),num=(v,d=1)=>Number(v).toLocaleString('ru-RU',{maximumFractionDigits:d}),money=v=>num(v,2),today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Minsk'}).format(new Date());
const KEY='reis-local-v1';let data={version:1,cars:[],routes:[],trips:[],settings:{price:0}},page='overview',period='month',search='',storageError=false;
try{const saved=localStorage.getItem(KEY);if(saved){const parsed=JSON.parse(saved);if(!validData(parsed))throw Error();data=parsed}}catch{storageError=true}
function persist(next){try{localStorage.setItem(KEY,JSON.stringify(next));data=next;return true}catch{toast('Не удалось сохранить. Освободите память или экспортируйте данные.');return false}}
function mutate(fn){const next=structuredClone(data);fn(next);return persist(next)}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4200)}
const items=[['overview','◫','Обзор'],['history','↗','Поездки'],['routes','⌁','Маршруты'],['cars','▱','Машины'],['settings','⚙','Настройки']];
const name=r=>[r.start,...r.legs.map(l=>l.to),...(r.round?[r.start]:[])].join(' → '),calc=t=>calculate(totalKm(t.route),t.consumption,t.price,t.fee,t.compensation);
function filtered(){const now=today();return data.trips.filter(t=>(period==='all'||period==='month'&&t.date.slice(0,7)===now.slice(0,7)||period==='week'&&t.date<=now&&t.date>=new Date(Date.parse(now+'T12:00:00Z')-6*86400000).toISOString().slice(0,10))&&(!search||name(t.route).toLowerCase().includes(search.toLowerCase())||t.note.toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date))}
function totals(ts){return ts.reduce((s,t)=>{const c=calc(t);for(const k of['km','liters','cost','due','net'])s[k]+=c[k];if(!t.paid)s.unpaid+=c.due;return s},{km:0,liters:0,cost:0,due:0,net:0,unpaid:0})}
const heading=(title,sub,action='')=>`<div class="page-heading"><div><h1>${title}</h1></div>${action}</div>`;
const addTrip='';
const periods=()=>`<div class="period">${[['week','7 дней'],['month','Этот месяц'],['all','Всё время']].map(([v,l])=>`<button data-period="${v}" class="${period===v?'active':''}">${l}</button>`).join('')}</div>`;
const empty=(title,text,button='')=>`<div class="empty"><div class="empty-icon">↗</div><h3>${title}</h3><p>${text}</p>${button}</div>`;
const carSVG='<svg viewBox="0 0 220 80" aria-hidden="true"><path d="M22 51l8-18 38-6 22-19h59l28 24 23 8 5 20h-22m-33 0H73m-32 0H22v-9M68 27h101M93 12l-17 15m49-15v15m24-15 16 15M31 41h20m128 0h16"/><circle cx="57" cy="59" r="15"/><circle cx="167" cy="59" r="15"/><circle cx="57" cy="59" r="6"/><circle cx="167" cy="59" r="6"/></svg>';
function stats(ts){const t=totals(ts);return `<div class="stats">${[['Рейсов записано',ts.length,'','За выбранный период'],['Пройдено',num(t.km),'км','Весь маршрут учтён'],['На топливо',money(t.cost),'BYN',`${num(t.liters)} л по расчёту`],['Начислено',money(t.due),'BYN','Рейсы и топливо']].map(([l,v,u,n])=>`<div class="stat"><div class="stat-label">${l}</div><div class="stat-number">${v} <small>${u}</small></div></div>`).join('')}</div>`}
function chart(){const end=today(),days=Array.from({length:7},(_,i)=>new Date(Date.parse(end+'T12:00:00Z')-(6-i)*86400000).toISOString().slice(0,10));const values=days.map(d=>totals(data.trips.filter(t=>t.date===d)).km),max=Math.max(...values,1);return `<div class="panel"><div class="panel-head"><h2>На дороге</h2><span class="tag">ПОСЛЕДНИЕ 7 ДНЕЙ</span></div><div class="chart" role="img" aria-label="Пробег за 7 дней: ${days.map((d,i)=>d+': '+values[i]+' км').join(', ')}">${days.map((d,i)=>`<div class="chart-col"><span class="chart-value">${values[i]?num(values[i]):'—'}</span><div class="bar" style="height:${Math.max(2,values[i]/max*112)}px"></div><span class="chart-label">${new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{weekday:'short'})}</span></div>`).join('')}</div></div>`}
function tripRows(ts){if(!ts.length)return empty('Пока ни одного рейса','Запишите первую поездку — здесь появятся маршрут, топливо и сумма к получению.',addTrip);let previous='';return ts.map(t=>{let date='';if(previous!==t.date){previous=t.date;date=`<div class="date-label">${new Date(t.date+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'})}</div>`}const c=calc(t);return date+`<div class="trip-row"><div class="route-icon">↗</div><div><button class="quiet trip-name" style="padding:0;min-height:32px;border:0;text-align:left" data-action="trip" data-id="${esc(t.id)}">${esc(name(t.route))}</button><div class="trip-meta">${esc(t.carName)} · ${num(c.km)} км · ${num(c.liters)} л${t.note?' · '+esc(t.note):''}</div></div><div class="trip-right">${money(c.due)} BYN<small>топливо ${money(c.cost)} BYN</small></div></div>`}).join('')}
function render(){ $('#nav').innerHTML=items.filter(([v])=>!['cars','routes'].includes(v)).map(([v,i,l])=>`<button data-page="${v}" class="${v===page||(['cars','routes'].includes(page)&&v==='settings')?'active':''}"><span class="nav-icon">${i}</span>${l}</button>`).join('')+'<button class="nav-add" data-action="trip" aria-label="Новая поездка"><span aria-hidden="true">＋</span></button>';$('#breadcrumb').textContent='Рабочий сезон / '+items.find(i=>i[0]===page)[2];const ts=filtered();let html='';if(page==='overview'){const car=data.cars[0];html=heading('Обзор','Поездки, топливо и расчёты — всё в одном месте.',addTrip)+periods()+stats(ts)+`<div class="dashboard-grid">${chart()}<div class="panel"><div class="panel-head"><h2>Ваша машина</h2><span class="tag">ГАРАЖ</span></div><div class="car-art">${carSVG}</div>${car?`<h3>${esc(car.name)}</h3><div class="split"><span>Средний расход</span><strong>${num(car.consumption)} л / 100 км</strong></div><button class="quiet" data-page="cars" style="width:100%">Открыть гараж ↗</button>`:`<h3>Нет машины</h3><button class="quiet" data-action="car" style="width:100%;margin-top:12px">＋ Добавить машину</button>`}</div></div><div class="section-head"><h2>Последние поездки</h2><button class="quiet" data-page="history">Вся история ↗</button></div>${tripRows(ts.slice(0,4))}`}
if(page==='history')html=heading('История поездок','Маршруты и расчёты, к которым легко вернуться.',addTrip)+periods()+stats(ts)+`<div class="section-head"><h2>Рейсы по дням</h2><button class="quiet" data-action="csv">Экспорт CSV ↓</button></div><input class="search" id="search" aria-label="Поиск поездок" placeholder="Поиск по маршруту или заметке" value="${esc(search)}">`+tripRows(ts)+`<div class="panel" style="margin-top:25px"><h2>Итоги периода</h2>${[['Начислено',totals(ts).due],['Расходы на топливо',totals(ts).cost],['После топлива',totals(ts).net]].map(([l,v])=>`<div class="metric-line"><span>${l}</span><strong>${money(v)} BYN</strong></div>`).join('')}</div>`;
if(page==='routes')html=heading('Маршруты','Сохраните маршрут и выбирайте его в один шаг.','<button class="primary" data-action="route">＋ Маршрут</button>')+(data.routes.length?`<div class="cards">${data.routes.map(r=>`<div class="panel"><div class="eyebrow">${r.round?'ТУДА И ОБРАТНО':'В ОДНУ СТОРОНУ'}</div><h2>${esc(name(r))}</h2><p>${num(totalKm(r))} км · ${r.legs.length} участков</p><div class="card-actions"><button data-action="use-route" data-id="${esc(r.id)}">Новая поездка ↗</button><button class="quiet" data-action="route" data-id="${esc(r.id)}">Изменить</button><button class="quiet danger" data-action="delete-route" data-id="${esc(r.id)}">Удалить</button></div></div>`).join('')}</div>`:empty('Маршруты под рукой','Например: Могилёв → Минск → Марьина Горка. Укажите километраж каждого участка.','<button class="primary" data-action="route">＋ Первый маршрут</button>'));
if(page==='cars')html=heading('Машины','Машина и расход — основа точного расчёта.','<button class="primary" data-action="car">＋ Машина</button>')+(data.cars.length?`<div class="cards">${data.cars.map(c=>`<div class="panel"><div class="car-art">${carSVG}</div><h2>${esc(c.name)}</h2><div class="split"><span>Средний расход</span><strong>${num(c.consumption)} л / 100 км</strong></div><div class="card-actions"><button data-action="car" data-id="${esc(c.id)}">Изменить</button><button class="quiet danger" data-action="delete-car" data-id="${esc(c.id)}">Удалить</button></div></div>`).join('')}</div>`:empty('На чём отправимся?','Укажите название машины и средний расход из своих наблюдений.','<button class="primary" data-action="car">＋ Добавить машину</button>'));
if(page==='settings')html=heading('Настройки','Данные остаются в этом браузере на этом устройстве.')+`<div class="panel settings-block settings-links"><button class="quiet" data-page="cars"><span>▱ Машины</span><span>↗</span></button><button class="quiet" data-page="routes"><span>⌁ Маршруты</span><span>↗</span></button></div><div class="panel settings-block"><h2>Цена топлива по умолчанию</h2><p class="panel-sub">Литры и стоимость рассчитываются автоматически по маршруту и расходу машины.</p><form id="settings-form"><label>Цена, BYN / л<input name="price" type="number" min="0" max="1000" step="0.001" value="${data.settings.price}" required></label><button class="primary" style="margin-top:16px">Сохранить цену</button></form></div><div class="panel settings-block"><h2>Резервная копия</h2><p>Сохраните файл перед очисткой браузера или сменой телефона.</p><div class="card-actions"><button data-action="export">Скачать JSON ↓</button><button class="quiet" data-action="import">Восстановить из файла</button></div><input id="import-file" type="file" accept="application/json,.json" hidden><div class="notice">Телефоны не синхронизируются автоматически. Для переноса записей отправьте резервную копию на другое устройство и восстановите её там. Импорт заменяет текущие данные после подтверждения.</div></div><div class="panel settings-block"><h2>Всегда под рукой</h2><p>В Chrome выберите «Установить приложение» или «Добавить на главный экран». В Safari: «Поделиться» → «На экран Домой».</p><div class="notice" id="offline-status">Офлайн-доступ подготавливается…</div><p class="hint">Расход топлива расчётный: километры × расход / 100. Пробки, прогрев и нагрузка могут менять фактический расход. Километраж указывается вручную.</p></div>`;
$('#content').innerHTML=html;if(page==='settings'){navigator.serviceWorker?.ready.then(()=>{if($('#offline-status'))$('#offline-status').textContent='Приложение сохранено для работы без интернета. Откройте его один раз онлайн на каждом устройстве.'});$('#settings-form').onsubmit=e=>{e.preventDefault();if(mutate(d=>d.settings.price=Number(new FormData(e.target).get('price'))))toast('Цена сохранена')};$('#import-file').onchange=importFile}if(page==='history')$('#search').oninput=e=>{search=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}}
function modal(title,body){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#modal').showModal()}
$('#close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
function carForm(carId){const c=data.cars.find(c=>c.id===carId);modal(c?'Изменить машину':'Добавить машину',`<form id="car-form" class="fields"><label class="full">Название машины<input name="name" maxlength="100" placeholder="Например, Volkswagen Passat" value="${esc(c?.name||'')}" required></label><label class="full">Средний расход, л / 100 км<input name="consumption" type="number" min="0.1" max="100" step="0.1" placeholder="Например, 8.5" value="${c?.consumption||''}" required></label><div class="form-actions full"><button class="primary">Сохранить машину</button></div></form>`);$('#car-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),v={id:c?.id||id(),name:f.get('name').trim(),consumption:Number(f.get('consumption'))};if(!v.name)return;if(mutate(d=>{const i=d.cars.findIndex(x=>x.id===v.id);i<0?d.cars.push(v):d.cars[i]=v})){$('#modal').close();render();toast('Машина сохранена')}}}
function routeFields(r){return `<label>Откуда<input id="start" maxlength="100" placeholder="Могилёв" value="${esc(r?.start||'')}" required></label><div id="stops"></div><button type="button" class="quiet" id="add-stop">＋ Ещё остановка</button><label class="check"><input type="checkbox" id="round" ${r?.round?'checked':''}>Вернуться тем же путём (километраж × 2)</label><p class="hint">Для другого обратного пути добавьте его отдельными участками.</p>`}
function stopRow(l={to:'',km:''}){const el=document.createElement('div');el.className='stop';el.innerHTML=`<label>Куда<input class="to" maxlength="100" value="${esc(l.to)}" placeholder="Минск" required></label><label>Участок, км<input class="km" type="number" min="0.1" max="100000" step="0.1" value="${l.km}" required></label><button type="button" aria-label="Удалить участок" class="remove-stop">×</button>`;if(l.coords)el.dataset.coords=l.coords;$('#stops').append(el);el.querySelector('button').onclick=()=>{if($('#stops').children.length>1)el.remove();$('#stops').dispatchEvent(new Event('input',{bubbles:true}))}}
function setupRoute(r){(r?.legs||[{to:'',km:''}]).forEach(stopRow);$('#add-stop').onclick=()=>{if($('#stops').children.length<30)stopRow()}}
function readRoute(){return{start:$('#start').value.trim(),legs:[...document.querySelectorAll('.stop')].map(el=>({to:el.querySelector('.to').value.trim(),km:Number(el.querySelector('.km').value),...(el.dataset.coords?{coords:el.dataset.coords}:{})})),round:$('#round').checked}}
function routeForm(routeId){const r=data.routes.find(r=>r.id===routeId);modal(r?'Изменить маршрут':'Сохранить маршрут',`<form id="route-form">${routeFields(r)}<div class="form-actions"><button class="primary">Сохранить маршрут</button></div></form>`);setupRoute(r);$('#route-form').onsubmit=e=>{e.preventDefault();const v={id:r?.id||id(),...readRoute()};if(!v.start||v.legs.some(l=>!l.to))return;if(mutate(d=>{const i=d.routes.findIndex(x=>x.id===v.id);i<0?d.routes.push(v):d.routes[i]=v})){$('#modal').close();render();toast('Маршрут сохранён')}}}
function tripForm(tripId,routeId){const t=data.trips.find(t=>t.id===tripId),r=t?.route||data.routes.find(r=>r.id===routeId);if(!data.cars.length&&!t){modal('Сначала добавьте машину','<p>Для расчёта топлива нужен её средний расход.</p><div class="form-actions"><button class="primary" data-action="first-car">Добавить машину</button></div>');return}
openTripEditor(t?'Запись поездки':'Новая поездка',`<form id="trip-form"><div class="fields"><label>Дата поездки<input id="date" type="date" value="${t?.date||today()}" required></label><label>Машина<select id="car">${t?`<option value="snapshot">${esc(t.carName)} · ${num(t.consumption)} л (из записи)</option>`:''}${data.cars.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></label><label class="full">Сохранённый маршрут<select id="route-select"><option value="">Ввести свой маршрут</option>${data.routes.map(v=>`<option value="${esc(v.id)}" ${v.id===routeId?'selected':''}>${esc(name(v))}</option>`).join('')}</select></label></div><div style="margin-top:15px">${routeFields(r)}</div><div class="fields" style="margin-top:18px"><label class="full">Оплата за рейс, BYN<input id="fee" type="number" min="0" max="1000000000" step="0.01" value="${t?.fee??0}" required></label><label class="full">Заметка / хозяйство<input id="note" maxlength="500" placeholder="Обработка яблок, название точки…" value="${esc(t?.note||'')}"></label></div>${!t?'<label class="check"><input type="checkbox" id="save-route">Запомнить этот маршрут</label>':''}<div class="result" id="result" aria-live="polite"></div><div class="form-actions">${t?'<button type="button" class="quiet danger" data-action="delete-trip" data-id="'+esc(t.id)+'">Удалить</button>':''}<button class="primary">${t?'Сохранить изменения':'Записать поездку'}</button></div></form>`);setupRoute(r);
const fuelPrice=t?.price??data.settings.price;
const selectedCar=()=>$('#car').value==='snapshot'?{name:t.carName,consumption:t.consumption}:data.cars.find(c=>c.id===$('#car').value);
function result(){const c=calculate(totalKm(readRoute()),selectedCar().consumption,fuelPrice,Number($('#fee').value),(t?.compensation??true));$('#result').innerHTML=`<div class="fuel-summary"><span>Топливо</span><strong>${num(c.liters,2)} л</strong></div><div class="split"><span>${num(c.km)} км × ${num(selectedCar().consumption)} л / 100 км</span><span>${money(c.cost)} BYN</span></div><div class="hint">${fuelPrice>0?`Цена: ${money(fuelPrice)} BYN / л`:'Цена за литр задаётся в настройках.'}</div><div class="fuel-total"><span>Рейс + топливо</span><strong>${money(c.due)} BYN</strong></div>`}$('#trip-form').oninput=result;$('#trip-form').onchange=result;$('#route-select').onchange=()=>{const v=data.routes.find(r=>r.id===$('#route-select').value);if(v){$('#start').value=v.start;$('#round').checked=v.round;$('#stops').innerHTML='';v.legs.forEach(stopRow)}result()};result();$('#trip-form').onsubmit=e=>{e.preventDefault();const route=readRoute(),car=selectedCar();if(!route.start||route.legs.some(l=>!l.to))return;const v={id:t?.id||id(),date:$('#date').value,route,carName:car.name,consumption:car.consumption,price:fuelPrice,fee:Number($('#fee').value),compensation:(t?.compensation??true),paid:(t?.paid??false),note:$('#note').value.trim()};if(mutate(d=>{const i=d.trips.findIndex(x=>x.id===v.id);i<0?d.trips.push(v):d.trips[i]=v;if($('#save-route')?.checked)d.routes.push({id:id(),...route})})){closeTripEditor();render();toast('Поездка сохранена')}}}
function download(content,type,filename){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function csv(){const cell=v=>'"'+String(v).replaceAll('"','""')+'"',rows=[['Дата','Маршрут','Машина','км','Литры','Топливо BYN','Рейс BYN','Рейс и топливо BYN','Заметка'],...filtered().map(t=>{const c=calc(t);return[t.date,name(t.route),t.carName,c.km,c.liters.toFixed(2),c.cost.toFixed(2),t.fee,c.due.toFixed(2),t.note]})];download('\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8','reis-'+today()+'.csv')}
async function importFile(e){const f=e.target.files[0];if(!f)return;try{if(f.size>10000000)throw Error();const d=JSON.parse(await f.text());if(!validData(d))throw Error();modal('Восстановить резервную копию?',`<p>В файле: ${d.trips.length} поездок, ${d.routes.length} маршрутов, ${d.cars.length} машин.</p><div class="notice">Текущие записи будут заменены. Перед восстановлением можно скачать их копию.</div><div class="form-actions"><button id="backup-first">Скачать текущую копию</button><button class="primary" id="confirm-import">Заменить данные</button></div>`);$('#backup-first').onclick=()=>download(JSON.stringify(data,null,2),'application/json','reis-backup-'+today()+'.json');$('#confirm-import').onclick=()=>{if(persist(d)){$('#modal').close();render();toast('Данные восстановлены')}}}catch{toast('Файл не подходит: нужна корректная резервная копия Рейс.')}e.target.value=''}
function deleteRecord(kind,recordId){modal('Удалить запись?',`<p>Удаление ${kind==='trips'?'поездки':'записи'} нельзя отменить.${kind!=='trips'?' Сохранённые поездки останутся.':''}</p><div class="form-actions"><button id="cancel-delete">Оставить</button><button class="danger" id="confirm-delete">Удалить</button></div>`);$('#cancel-delete').onclick=()=>$('#modal').close();$('#confirm-delete').onclick=()=>{if(mutate(d=>d[kind]=d[kind].filter(x=>x.id!==recordId))){$('#modal').close();if(kind==='trips')closeTripEditor();render();toast('Запись удалена')}}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page){page=b.dataset.page;search='';render();window.scrollTo(0,0)}if(b.dataset.period){period=b.dataset.period;render()}const a=b.dataset.action,i=b.dataset.id;if(a==='trip')tripForm(i);if(a==='car')carForm(i);if(a==='route')routeForm(i);if(a==='use-route')tripForm(null,i);if(a==='first-car'){$('#modal').close();carForm()}if(a?.startsWith('delete-'))deleteRecord({'delete-trip':'trips','delete-car':'cars','delete-route':'routes'}[a],i);if(a==='export')download(JSON.stringify(data,null,2),'application/json','reis-backup-'+today()+'.json');if(a==='csv')csv();if(a==='import')$('#import-file').click()});
render();if(storageError)toast('Не удалось прочитать сохранённые данные. Исходная запись не перезаписана.');if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{if($('#offline-status'))$('#offline-status').textContent='Офлайн-версия пока недоступна. Откройте приложение по HTTPS и обновите страницу.'});


function closeTripEditor(){const editor=document.querySelector('#trip-editor');if(editor){editor.remove();document.querySelector('#nav .nav-add')?.focus()}}
function openTripEditor(title,body){closeTripEditor();document.querySelector('#dialog-body').innerHTML='';const editor=document.createElement('section');editor.id='trip-editor';editor.setAttribute('role','region');editor.setAttribute('aria-label',title);editor.innerHTML='<div class="editor-shell"><header class="editor-header"><h2>'+esc(title)+'</h2><button type="button" class="icon-button editor-close" aria-label="Закрыть поездку">✕</button></header><div class="editor-body">'+body+'</div></div>';document.body.append(editor);editor.querySelector('.editor-close').onclick=closeTripEditor;editor.querySelector('.editor-close').focus()}
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!document.querySelector('#modal').open)closeTripEditor()});
